import * as React from "react";
import { usePopper, Modifier } from "react-popper";
import { detectOverflow } from "@popperjs/core";
import { AppRootPortal } from "../AppRoot/AppRootPortal";
import { PopperArrow } from "../PopperArrow/PopperArrow";
import { HasRef } from "../../types";
import { usePlatform } from "../../hooks/usePlatform";
import { getClassName } from "../../helpers/getClassName";
import { useExternRef } from "../../hooks/useExternRef";
import { useIsomorphicLayoutEffect } from "../../lib/useIsomorphicLayoutEffect";
import "./Popper.css";

export type Placement =
  | "auto"
  | "auto-start"
  | "auto-end"
  | "top-start"
  | "top-end"
  | "bottom-start"
  | "bottom-end"
  | "right-start"
  | "right-end"
  | "left-start"
  | "left-end"
  | "top"
  | "bottom"
  | "left"
  | "right";

export interface PopperRenderContentProps {
  className: string;
}

export interface PopperCommonProps
  extends React.HTMLAttributes<HTMLDivElement>,
    HasRef<HTMLDivElement> {
  /**
   * По умолчанию компонент выберет наилучшее расположение сам. Но его можно задать извне с помощью этого свойства
   */
  placement?: Placement;
  forcePlacement?: Placement;
  /**
   * Отступ по вспомогательной оси
   */
  offsetSkidding?: number;
  /**
   * Отступ по главной оси
   */
  offsetDistance?: number;
  /**
   * Отображать ли стрелку, указывающую на якорный элемент
   */
  arrow?: boolean;
  /**
   * Стиль стрелки
   */
  arrowClassName?: string;
  /**
   * Выставлять ширину равной target элементу
   */
  sameWidth?: boolean;
  forcePortal?: boolean;
  onPlacementChange?: (data: { placement?: Placement }) => void;
  /**
   * Массив кастомных модификаторов для Popper (необходимо мемоизировать)
   */
  customModifiers?: Array<Modifier<string>>;
  /**
   * При передаче содержимого в `children`, он будет обёрнут во внутренний контейнер.
   *
   * Если хочется управлять этим контейнером, то используйте данную функцию.
   *
   * > ⚠️ Параметр `children` будет проигнорирован.
   */
  renderContent?(props: PopperRenderContentProps): React.ReactNode;
}

export interface PopperProps extends PopperCommonProps {
  targetRef: React.RefObject<HTMLElement>;
}

const ARROW_PADDING = 8;
const ARROW_WIDTH = 20;
const ARROW_HEIGHT = 8;

const preventOverflowModifier: Modifier<string> = {
  name: "preventOverflow",
  options: {
    mainAxis: false,
  },
};

const flipModifier: Modifier<string> = {
  name: "flip",
};

const MAX_SIZE_PADDING = 8;

/**
 * Считает, сколько высоты доступно попперу до края viewport с учётом итогового placement
 * @see https://github.com/atomiks/popper.js-max-size-modifier
 */
const maxSizeModifier: Modifier<string> = {
  name: "maxSize",
  enabled: true,
  phase: "main",
  requiresIfExists: ["offset", "preventOverflow", "flip"],
  fn: ({ state, name }) => {
    const overflow = detectOverflow(state, { padding: MAX_SIZE_PADDING });
    const { y = 0 } = state.modifiersData.preventOverflow || {};
    const side = state.placement.startsWith("top") ? "top" : "bottom";

    state.modifiersData[name] = {
      height: state.rects.popper.height - overflow[side] - y,
    };
  },
};

/**
 * Отдаёт доступную высоту содержимому поппера через CSS-переменную: сам поппер не ограничивается,
 * решение об ужатии принимает контент (например, список CustomSelectDropdown)
 */
const applyMaxSizeModifier: Modifier<string> = {
  name: "applyMaxSize",
  enabled: true,
  phase: "beforeWrite",
  requires: ["maxSize"],
  fn: ({ state }) => {
    state.elements.popper.style.setProperty(
      "--vkui_popper_max_height",
      `${state.modifiersData.maxSize.height}px`
    );
  },
};

const arrowModifier: Modifier<string> = {
  name: "arrow",
  options: {
    padding: ARROW_PADDING,
  },
};

const sameWidthModifier: Modifier<string> = {
  name: "sameWidth",
  enabled: true,
  phase: "beforeWrite",
  requires: ["computeStyles"],
  fn: ({ state }) => {
    state.styles.popper.width = `${state.rects.reference.width}px`;
  },
  effect: ({ state }) => {
    state.elements.popper.style.width = `${
      (state.elements.reference as HTMLElement).offsetWidth
    }px`;
  },
};

/**
 * @see https://vkcom.github.io/VKUI/#/Popper
 */
export const Popper = ({
  targetRef,
  children,
  getRef,
  forcePlacement,
  placement = "bottom-start",
  onPlacementChange,
  arrow,
  arrowClassName,
  sameWidth,
  offsetDistance = 8,
  offsetSkidding = 0,
  forcePortal = true,
  style: compStyles,
  customModifiers,
  renderContent,
  ...restProps
}: PopperProps) => {
  const [popperNode, setPopperNode] = React.useState<HTMLDivElement | null>(
    null
  );
  const [smallTargetOffsetSkidding, setSmallTargetOffsetSkidding] =
    React.useState(0);
  const platform = usePlatform();

  const setExternalRef = useExternRef<HTMLDivElement>(getRef, setPopperNode);

  const modifiers = React.useMemo(() => {
    const modifiers: Array<Modifier<string>> = [
      preventOverflowModifier,
      {
        name: "offset",
        options: {
          offset: [
            arrow ? offsetSkidding - smallTargetOffsetSkidding : offsetSkidding,
            arrow ? offsetDistance + ARROW_HEIGHT : offsetDistance,
          ],
        },
      },
      (!forcePlacement ? flipModifier : null) as Modifier<string>,
      maxSizeModifier,
      applyMaxSizeModifier,
    ].filter((e) => e);

    if (arrow) {
      modifiers.push(arrowModifier);
    }

    if (sameWidth) {
      modifiers.push(sameWidthModifier);
    }

    if (customModifiers) {
      modifiers.push(...customModifiers);
    }
    return modifiers;
  }, [
    arrow,
    sameWidth,
    smallTargetOffsetSkidding,
    offsetSkidding,
    offsetDistance,
    customModifiers,
  ]);

  const { styles, state, attributes } = usePopper(
    targetRef.current,
    popperNode,
    {
      placement: forcePlacement || placement,
      modifiers,
    }
  );

  const resolvedPlacement = state?.placement;
  const isEdgePlacement =
    !!resolvedPlacement && resolvedPlacement.includes("-"); // true, если поппер отрисован с краю

  // Если поппер рисуется с краю, то нужно опционально сместить его в тех случаях, когда стрелка не дотягивается до
  // таргета из-за маленьких размеров последнего
  useIsomorphicLayoutEffect(() => {
    if (arrow && isEdgePlacement) {
      const placementDirection =
        resolvedPlacement?.startsWith("bottom") ||
        resolvedPlacement?.startsWith("top")
          ? "vertical"
          : "horizontal";

      const arrowSize =
        placementDirection === "vertical" ? ARROW_WIDTH : ARROW_HEIGHT;
      const targetSize =
        (placementDirection === "vertical"
          ? targetRef.current?.offsetWidth
          : targetRef.current?.offsetHeight) ?? 0;

      if (targetSize < arrowSize + 2 * ARROW_PADDING) {
        setSmallTargetOffsetSkidding(ARROW_PADDING + arrowSize / 2);
      }
    } else {
      setSmallTargetOffsetSkidding(0);
    }
  }, [arrow, isEdgePlacement]);

  React.useEffect(() => {
    if (resolvedPlacement) {
      onPlacementChange && onPlacementChange({ placement: resolvedPlacement });
    }
  }, [onPlacementChange, resolvedPlacement]);

  const width = styles.popper?.width || compStyles?.width;

  const roundWidth = (value: number): number => {
    const decimal = value % 1;

    if (decimal >= 0.75) return Math.ceil(value);
    if (decimal >= 0.44) return Math.floor(value) + 0.5;

    return Math.floor(value);
  };

  const dropdown = (
    <div
      {...restProps}
      {...attributes.popper}
      vkuiClass={getClassName("Popper", platform)}
      ref={setExternalRef}
      style={{
        ...compStyles,
        ...styles.popper,
        width: typeof width === 'number'
          ? roundWidth(width)
          : (width?.includes('px')
            ? `${roundWidth(+width.replace('px', ''))}px`
            : width
          ),
      }}
    >
      {arrow && (
        <PopperArrow
          attributes={attributes.arrow}
          style={styles.arrow}
          arrowClassName={arrowClassName}
        />
      )}
      {renderContent ? (
        renderContent({ className: "Popper__content" })
      ) : (
        <div vkuiClass="Popper__content">{children}</div>
      )}
    </div>
  );

  return (
    <AppRootPortal forcePortal={forcePortal} vkuiClass="PopperPortal">
      {dropdown}
    </AppRootPortal>
  );
};
